import {
  messageBlocks,
  messageInline,
  type MessageText,
} from "@/lib/message-format";

function escapeHtml(text: string) {
  return text.replace(/[&<>"']/g, (character) => {
    return {
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#39;",
    }[character]!;
  });
}

/** Render plain-text input without interpreting any authored HTML. */
function linkedText(text: string) {
  return text
    .split(/(https?:\/\/[^\s<>"']+)/gi)
    .map((part, index) => {
      if (index % 2 === 0) return escapeHtml(part);
      // Leave sentence punctuation outside the link, retaining balanced URL parentheses.
      let url = part.replace(/[.,!?:;]+$/, "");
      while (
        url.endsWith(")") &&
        (url.match(/\)/g)?.length ?? 0) > (url.match(/\(/g)?.length ?? 0)
      ) {
        url = url.slice(0, -1);
      }
      try {
        const parsed = new URL(url);
        if (!parsed.hostname) return escapeHtml(part);
      } catch {
        return escapeHtml(part);
      }
      const escaped = escapeHtml(url);
      return `<a href="${escaped}">${escaped}</a>${escapeHtml(part.slice(url.length))}`;
    })
    .join("")
    .replace(/\r\n|\r|\n/g, "<br>\n");
}

function inlineHtml(text: MessageText) {
  return messageInline(text)
    .map((part) =>
      part.bold
        ? `<strong>${linkedText(part.text)}</strong>`
        : linkedText(part.text),
    )
    .join("");
}

export function emailHtml(body: string) {
  const content = messageBlocks(body)
    .map((block) => {
      if (block.kind === "text") return inlineHtml(block);
      const start = block.kind === "ol" ? ` start="${block.number}"` : "";
      return `<${block.kind}${start} style="margin:0;padding-left:24px">${block.items.map((item) => `<li>${inlineHtml(item)}</li>`).join("")}</${block.kind}>`;
    })
    .join("");
  return `<!doctype html><html><head><meta charset="utf-8"></head><body><div style="width:100%;max-width:640px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;text-align:left;overflow-wrap:anywhere;word-wrap:break-word">${content}</div></body></html>`;
}
